-- Mexico deep-dive page translations: page fields, stats, cards,
-- lifecycle card + statuses, steps, portal.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Compensación centralizada (red de PACs)', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Los catálogos del Anexo 20, las especificaciones de complementos y las disposiciones de sanciones continúan evolucionando — confirme los requisitos actuales directamente con el SAT o su PAC antes de construir una integración.', 'El sistema CFDI de México tiene más de una década — la actividad interesante hoy son las actualizaciones de versión y el mantenimiento anual de catálogos, no una reconstrucción fundamental.', 'El Anexo 20 es la referencia maestra — pero casi todos los tipos de transacción específicos añaden su propio complemento adicional.', 'La compensación de México opera a través de certificadores privados autorizados por el gobierno (PACs) en lugar de un único portal gubernamental — más cercano al modelo PA de Francia que al SDI de Italia.', 'No existe un único paso de "regístrese aquí" — el cumplimiento pasa por su RFC, su e.firma y su relación con el PAC elegido.', 'La reforma de 2026 endureció considerablemente los mecanismos de fiscalización del SAT — trate la autenticidad del CFDI como un riesgo de cumplimiento genuino, no solo un ejercicio de formato.' FROM countries WHERE name_en = 'Mexico';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Zentralisiertes Clearing (PAC-Netzwerk)', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Anexo-20-Kataloge, Complemento-Spezifikationen und Strafvorschriften entwickeln sich weiter — bestätigen Sie aktuelle Anforderungen direkt beim SAT oder Ihrem PAC, bevor Sie eine Integration aufbauen.', 'Mexikos CFDI-System ist über ein Jahrzehnt alt — die interessante Aktivität heute sind Versionsupgrades und jährliche Katalogpflege, kein grundlegender Neuaufbau.', 'Anexo 20 ist die maßgebliche Referenz — doch fast jeder spezifische Transaktionstyp fügt sein eigenes zusätzliches Complemento hinzu.', 'Mexikos Clearing läuft über private, staatlich autorisierte Zertifizierer (PACs) statt über ein einziges Regierungsportal — näher am französischen PA-Modell als am italienischen SDI.', 'Es gibt keinen einzigen "Hier registrieren"-Schritt — die Compliance läuft über Ihre RFC, Ihre e.firma und Ihre gewählte PAC-Beziehung.', 'Die Reform von 2026 verschärfte die Durchsetzungsbefugnisse des SAT erheblich — behandeln Sie die CFDI-Echtheit als echtes Compliance-Risiko, nicht nur als Formatierungsübung.' FROM countries WHERE name_en = 'Mexico';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Contrôle centralisé (réseau de PAC)', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les catalogues Anexo 20, les spécifications des complementos et les dispositions de sanctions continuent d''évoluer — confirmez les exigences actuelles directement auprès du SAT ou de votre PAC avant de construire une intégration.', 'Le système CFDI du Mexique a plus d''une décennie — l''activité intéressante aujourd''hui concerne les mises à niveau de version et la maintenance annuelle des catalogues, pas une refonte fondamentale.', 'L''Anexo 20 est la référence maîtresse — mais presque chaque type de transaction spécifique ajoute son propre complemento supplémentaire.', 'Le contrôle mexicain passe par des certificateurs privés autorisés par le gouvernement (PAC) plutôt que par un portail gouvernemental unique — plus proche du modèle PA français que du SDI italien.', 'Il n''existe pas d''étape unique « inscrivez-vous ici » — la conformité passe par votre RFC, votre e.firma et votre relation avec le PAC choisi.', 'La réforme de 2026 a considérablement renforcé les moyens d''application du SAT — traitez l''authenticité du CFDI comme un véritable risque de conformité, pas seulement un exercice de mise en forme.' FROM countries WHERE name_en = 'Mexico';

