INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Especificación base', '[["Formato", "XML, según el Anexo 20 de la Resolución Miscelánea Fiscal vigente"], ["Versión actual", "CFDI 4.0"], ["Campos obligatorios", "RFC (emisor + receptor), régimen fiscal, código postal, Uso del CFDI, forma/método de pago"]]', 'El Anexo 20 dicta no solo qué campos son obligatorios, sino los valores aceptables para cada uno — un XML con todos los campos requeridos presentes aún puede ser rechazado si un código de régimen fiscal es inválido.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Basisspezifikation', '[["Format", "XML, gemäß Anexo 20 der aktuellen Resolución Miscelánea Fiscal"], ["Aktuelle Version", "CFDI 4.0"], ["Pflichtfelder", "RFC (Aussteller + Empfänger), Steuerregime, Postleitzahl, Uso del CFDI, Zahlungsform/-methode"]]', 'Anexo 20 legt nicht nur fest, welche Felder erforderlich sind, sondern auch die zulässigen Werte für jedes — ein XML mit allen erforderlichen Feldern kann dennoch abgelehnt werden, wenn ein Steuerregimecode ungültig ist.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Spécification de base', '[["Format", "XML, selon l''Anexo 20 de la Resolución Miscelánea Fiscal actuelle"], ["Version actuelle", "CFDI 4.0"], ["Champs obligatoires", "RFC (émetteur + destinataire), régime fiscal, code postal, Uso del CFDI, forme/méthode de paiement"]]', 'L''Anexo 20 dicte non seulement quels champs sont requis, mais aussi les valeurs acceptables pour chacun — un XML avec tous les champs requis présents peut encore être rejeté si un code de régime fiscal est invalide.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Complementos — la verdadera complejidad', '[["Cantidad activa", "26+ complementos especializados"], ["Ejemplos comunes", "Nómina 1.2 (nómina), Pagos 2.0 (parcialidades), Carta Porte 3.1 (transporte)"], ["Estructura", "Espacio de nombres y reglas de validación propios, superpuestos al CFDI base"]]', 'Un CFDI de nómina o transporte debe satisfacer simultáneamente el Anexo 20 y el anexo técnico de su complemento específico — no son complementos opcionales una vez que su tipo de transacción los requiere.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Complementos — die eigentliche Komplexität', '[["Aktive Anzahl", "26+ spezialisierte Complementos"], ["Häufige Beispiele", "Nómina 1.2 (Gehaltsabrechnung), Pagos 2.0 (Ratenzahlung), Carta Porte 3.1 (Fracht)"], ["Struktur", "Eigener Namespace + Validierungsregeln, dem Basis-CFDI übergelagert"]]', 'Ein CFDI für Gehaltsabrechnung oder Fracht muss gleichzeitig Anexo 20 und den technischen Anhang seines spezifischen Complemento erfüllen — dies sind keine optionalen Zusätze, sobald Ihr Transaktionstyp sie erfordert.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Complementos — la véritable complexité', '[["Nombre actif", "26+ complementos spécialisés"], ["Exemples courants", "Nómina 1.2 (paie), Pagos 2.0 (paiements échelonnés), Carta Porte 3.1 (fret)"], ["Structure", "Espace de noms et règles de validation propres, superposés au CFDI de base"]]', 'Un CFDI pour la paie ou le fret doit satisfaire simultanément l''Anexo 20 et l''annexe technique de son complemento spécifique — ce ne sont pas des ajouts optionnels une fois que votre type de transaction les exige.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Catálogos', '[["Tipos", "Uso CFDI, Régimen Fiscal, Productos y Servicios, Formas/Métodos de Pago"], ["Frecuencia de actualización", "Periódica — típicamente anual"]]', 'Confirme que su sistema o PAC haya incorporado la última versión del catálogo al inicio de cada ejercicio fiscal — usar un código retirado es una de las causas más comunes de rechazos al timbrar.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Kataloge', '[["Typen", "Uso CFDI, Régimen Fiscal, Productos y Servicios, Formas/Métodos de Pago"], ["Aktualisierungsrhythmus", "Periodisch — typischerweise jährlich"]]', 'Bestätigen Sie, dass Ihr System oder PAC die neueste Katalogversion zu Beginn jedes Geschäftsjahres übernommen hat — die Verwendung eines ausgemusterten Codes ist eine der häufigsten Ursachen für Stempelablehnungen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Catalogues', '[["Types", "Uso CFDI, Régimen Fiscal, Productos y Servicios, Formas/Métodos de Pago"], ["Cadence de mise à jour", "Périodique — généralement annuelle"]]', 'Confirmez que votre système ou PAC a intégré la dernière version du catalogue au début de chaque exercice fiscal — utiliser un code retiré est l''une des causes les plus courantes de rejets lors de l''estampillage.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Identidad y firma', '[["Sello Digital", "Sello digital propio del emisor"], ["Sello del PAC", "Aplicado durante el timbrado"], ["Folio Fiscal", "UUID asignado al timbrar — el identificador único permanente"]]', 'El Folio Fiscal (UUID) es a lo que hace referencia todo sistema posterior — trátelo de la misma manera que trataría la chave de acesso de Brasil o el número de referencia SDI de Italia.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Identität & Signatur', '[["Sello Digital", "Eigener digitaler Stempel des Ausstellers"], ["PAC-Stempel", "Angewendet während des Timbrado"], ["Folio Fiscal", "Beim Stempeln zugewiesene UUID — der dauerhafte eindeutige Bezeichner"]]', 'Der Folio Fiscal (UUID) ist die Referenz, auf die sich jedes nachgelagerte System bezieht — behandeln Sie ihn genauso wie Brasiliens chave de acesso oder Italiens SDI-Referenznummer.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Identité et signature', '[["Sello Digital", "Cachet numérique propre à l''émetteur"], ["Cachet PAC", "Appliqué lors du timbrado"], ["Folio Fiscal", "UUID attribué lors de l''estampillage — l''identifiant unique permanent"]]', 'Le Folio Fiscal (UUID) est ce à quoi tout système en aval fait référence — traitez-le de la même manière que la chave de acesso brésilienne ou le numéro de référence SDI italien.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'PACs — Proveedores Autorizados de Certificación', '[["Función", "Terceros autorizados por el SAT que validan, sellan y transmiten CFDIs"], ["Modelos de precios", "Fracciones de un peso por sello a alto volumen; varios pesos por uso"], ["Soporte de complementos", "Varía según el proveedor — no todos los PACs admiten todos los complementos"]]', 'Compare el costo total de propiedad a su volumen mensual real en lugar de las tarifas por sello anunciadas, y verifique que el PAC elegido realmente admita cada complemento que su empresa necesita (Carta Porte para transporte, Comercio Exterior para comercio internacional) antes de comprometerse.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'PACs — Proveedores Autorizados de Certificación', '[["Rolle", "Vom SAT autorisierte Drittanbieter, die CFDIs validieren, stempeln und übermitteln"], ["Preismodelle", "Bruchteile eines Pesos pro Stempel bei hohem Volumen; mehrere Pesos bei Pay-as-you-go"], ["Complemento-Unterstützung", "Variiert je nach Anbieter — nicht jeder PAC unterstützt jedes Complemento"]]', 'Vergleichen Sie die Gesamtbetriebskosten bei Ihrem tatsächlichen monatlichen Volumen statt der beworbenen Preise pro Stempel, und stellen Sie sicher, dass Ihr gewählter PAC tatsächlich jedes von Ihrem Unternehmen benötigte Complemento unterstützt (Carta Porte für Fracht, Comercio Exterior für internationalen Handel), bevor Sie sich festlegen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'PACs — Proveedores Autorizados de Certificación', '[["Rôle", "Tiers autorisés par le SAT qui valident, estampillent et transmettent les CFDI"], ["Modèles tarifaires", "Fractions de peso par estampille à volume élevé ; plusieurs pesos à l''usage"], ["Support des complementos", "Varie selon le fournisseur — tous les PAC ne prennent pas en charge tous les complementos"]]', 'Comparez le coût total de possession à votre volume mensuel réel plutôt qu''aux tarifs affichés par estampille, et vérifiez que le PAC choisi prend réellement en charge chaque complemento dont votre entreprise a besoin (Carta Porte pour le fret, Comercio Exterior pour le commerce international) avant de vous engager.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Gestión de rechazos', '[["Causa común", "Códigos de catálogo retirados, datos de receptor no coincidentes"], ["Patrón de causa raíz", "Captura manual de datos"]]', 'Las plataformas de facturación modernas validan los datos del receptor y la vigencia del catálogo antes de llegar siquiera al PAC — automatizar esta verificación previa elimina en gran medida las categorías de rechazo más comunes.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Umgang mit Ablehnungen', '[["Häufige Ursache", "Ausgemusterte Katalogcodes, nicht übereinstimmende Empfängerdaten"], ["Grundursachenmuster", "Manuelle Datenerfassung"]]', 'Moderne Rechnungsplattformen validieren Empfängerdaten und Katalogaktualität, bevor sie überhaupt den PAC erreichen — die Automatisierung dieser Vorprüfung eliminiert weitgehend die häufigsten Ablehnungskategorien.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Gestion des rejets', '[["Cause fréquente", "Codes de catalogue retirés, données de destinataire non concordantes"], ["Schéma de cause première", "Saisie manuelle des données"]]', 'Les plateformes de facturation modernes valident les données du destinataire et l''actualité du catalogue avant même d''atteindre le PAC — automatiser cette pré-vérification élimine largement les catégories de rejet les plus courantes.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Corrección de un CFDI', '[["Notas de crédito", "Regidas por el Apéndice 4 — el código correcto de \"tipo de relación\" importa"], ["Confusión común", "01 (nota de crédito) vs. 03 (devolución de mercancía) vs. 07 (aplicación de anticipo)"]]', 'Elegir el código de tipo de relación incorrecto en una corrección es una fuente frecuente de problemas de conciliación posteriores — verifique cuál de los tres aplica a su escenario específico antes de emitir.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Korrektur eines CFDI', '[["Gutschriften", "Geregelt durch Apéndice 4 — der korrekte \"tipo de relación\"-Code ist entscheidend"], ["Häufige Verwechslung", "01 (Gutschrift) vs. 03 (Warenrücksendung) vs. 07 (Anwendung einer Vorauszahlung)"]]', 'Die Wahl des falschen Beziehungstyp-Codes bei einer Korrektur ist eine häufige Quelle nachgelagerter Abstimmungsprobleme — prüfen Sie, welcher der drei auf Ihr spezifisches Szenario zutrifft, bevor Sie ausstellen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Correction d''un CFDI', '[["Notes de crédit", "Régies par l''Apéndice 4 — le bon code de « tipo de relación » compte"], ["Confusion courante", "01 (note de crédit) vs. 03 (retour de marchandise) vs. 07 (application d''un acompte)"]]', 'Choisir le mauvais code de type de relation lors d''une correction est une source fréquente de problèmes de rapprochement en aval — vérifiez lequel des trois s''applique à votre scénario spécifique avant d''émettre.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'es', 'El flujo de compensación (timbrado)', NULL, 'Desde el CFDI 4.0, la validación incluye la verificación previa del RFC, nombre y régimen fiscal del receptor contra el propio registro de contribuyentes del SAT — un XML internamente consistente aún puede fallar si los datos del receptor no coinciden con lo que el SAT tiene registrado.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Mexico';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'de', 'Der Clearing-Ablauf (timbrado)', NULL, 'Seit CFDI 4.0 umfasst die Validierung eine Vorabprüfung von RFC, Name und Steuerregime des Empfängers gegen das eigene Steuerpflichtigenregister des SAT — ein intern konsistentes XML kann dennoch scheitern, wenn die Empfängerdaten nicht mit den beim SAT hinterlegten übereinstimmen.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Mexico';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'fr', 'Le flux de contrôle (timbrado)', NULL, 'Depuis le CFDI 4.0, la validation inclut une pré-vérification du RFC, du nom et du régime fiscal du destinataire par rapport au propre registre des contribuables du SAT — un XML interne cohérent peut néanmoins échouer si les informations du destinataire ne correspondent pas à celles enregistrées par le SAT.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Mexico';

