INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme su registro de RFC y régimen fiscal', 'Su Registro Federal de Contribuyentes y régimen fiscal registrado son la base a la que hace referencia cada CFDI — asegúrese de que estén actualizados ante el SAT.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie Ihre RFC- und Steuerregime-Registrierung', 'Ihr Registro Federal de Contribuyentes und Ihr registriertes Steuerregime sind die Grundlage, auf die sich jedes CFDI bezieht — stellen Sie sicher, dass diese beim SAT aktuell sind.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez votre inscription RFC et régime fiscal', 'Votre Registro Federal de Contribuyentes et votre régime fiscal enregistré constituent la base à laquelle chaque CFDI fait référence — assurez-vous qu''ils sont à jour auprès du SAT.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Obtenga su e.firma y Certificado de Sello Digital', 'Estas credenciales son las que le permiten firmar CFDIs antes de enviarlos a un PAC.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Beschaffen Sie Ihre e.firma und Ihr Certificado de Sello Digital', 'Diese Anmeldedaten ermöglichen es Ihnen, CFDIs vor der Übermittlung an einen PAC zu signieren.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Obtenez votre e.firma et votre Certificado de Sello Digital', 'Ces identifiants sont ce qui vous permet de signer les CFDI avant leur soumission à un PAC.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Seleccione un PAC según sus necesidades de complementos', 'Si maneja transporte de carga, confirme el soporte completo de Carta Porte. Si comercia internacionalmente, confirme el soporte de Comercio Exterior. Verifique el historial del PAC en la implementación oportuna de nuevas versiones de complementos.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie einen PAC basierend auf Ihren Complemento-Bedürfnissen', 'Wenn Sie Fracht abwickeln, bestätigen Sie die vollständige Carta-Porte-Unterstützung. Wenn Sie international handeln, bestätigen Sie die Comercio-Exterior-Unterstützung. Überprüfen Sie die Erfolgsbilanz des PAC bei der zügigen Implementierung neuer Complemento-Versionen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Sélectionnez un PAC selon vos besoins en complementos', 'Si vous gérez le fret, confirmez le support complet de Carta Porte. Si vous commercez à l''international, confirmez le support de Comercio Exterior. Vérifiez les antécédents du PAC en matière de mise en œuvre rapide des nouvelles versions de complementos.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Mapee sus datos al Anexo 20 y catálogos vigentes', 'Confirme que está usando las versiones de catálogo de este ejercicio fiscal — los códigos obsoletos son la fuente más común de rechazos al timbrar.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Ordnen Sie Ihre Daten dem aktuellen Anexo 20 und den Katalogen zu', 'Bestätigen Sie, dass Sie die Katalogversionen dieses Geschäftsjahres verwenden — veraltete Codes sind die häufigste Ursache für Stempelablehnungen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Associez vos données à l''Anexo 20 et aux catalogues actuels', 'Confirmez que vous utilisez les versions de catalogue de cet exercice fiscal — les codes obsolètes sont la source la plus courante de rejets lors de l''estampillage.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Prevalide los datos del receptor antes de enviarlos', 'Verifique proactivamente el RFC, nombre y régimen fiscal del receptor contra el registro del SAT — esto detecta la validación más estricta del CFDI 4.0 antes de que se convierta en un rechazo.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Validieren Sie Empfängerdaten vor der Übermittlung vorab', 'Prüfen Sie RFC, Name und Steuerregime des Empfängers proaktiv gegen das SAT-Register — dies erkennt die strengere Validierung von CFDI 4.0, bevor sie zu einer Ablehnung wird.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Pré-validez les données du destinataire avant la soumission', 'Vérifiez de manière proactive le RFC, le nom et le régime fiscal du destinataire par rapport au registre du SAT — cela permet de détecter la validation plus stricte du CFDI 4.0 avant qu''elle ne se transforme en rejet.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Implemente sus complementos requeridos', 'Desarrolle el soporte de Carta Porte, Pagos, Comercio Exterior o Nómina según lo requieran sus tipos de transacción — cada uno tiene su propio anexo técnico sobre el CFDI base.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Implementieren Sie Ihre erforderlichen Complementos', 'Bauen Sie Unterstützung für Carta Porte, Pagos, Comercio Exterior oder Nómina auf, wie es Ihre Transaktionstypen erfordern — jedes hat seinen eigenen technischen Anhang zum Basis-CFDI.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Implémentez vos complementos requis', 'Développez le support de Carta Porte, Pagos, Comercio Exterior ou Nómina selon les besoins de vos types de transaction — chacun possède sa propre annexe technique en plus du CFDI de base.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure el archivo de 5 años', 'Conserve tanto los CFDIs en XML como sus sellos/UUIDs del PAC durante el período de retención legal.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 6;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Richten Sie eine 5-jährige Archivierung ein', 'Bewahren Sie sowohl die XML-CFDIs als auch deren PAC-Stempel/UUIDs für die gesetzliche Aufbewahrungsfrist auf.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 6;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez en place un archivage de 5 ans', 'Conservez à la fois les CFDI XML et leurs estampilles/UUID PAC pendant la période de conservation légale.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Mexico' AND ds.sort_order = 6;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '⚖️ Marco del Código Fiscal de la Federación', NULL, NULL, 'El incumplimiento del CFDI se sanciona bajo el código fiscal federal general de México — incluyendo, en casos graves, la clausura de establecimientos comerciales por infracciones repetidas o severas. Confirme las cifras vigentes con un asesor fiscal mexicano dadas las revisiones periódicas.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '⚖️ Rahmen des Código Fiscal de la Federación', NULL, NULL, 'CFDI-Nichteinhaltung wird nach Mexikos allgemeinem Bundessteuergesetz geahndet — einschließlich, in schwerwiegenden Fällen, der Schließung von Geschäftsräumen (clausura) bei wiederholten oder schweren Verstößen. Bestätigen Sie aktuelle Beträge angesichts periodischer Überarbeitungen bei einem mexikanischen Steuerberater.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '⚖️ Cadre du Código Fiscal de la Federación', NULL, NULL, 'Le non-respect du CFDI est sanctionné en vertu du code fiscal fédéral général du Mexique — y compris, dans les cas graves, la fermeture de locaux commerciaux (clausura) pour infractions répétées ou sévères. Confirmez les montants actuels auprès d''un conseiller fiscal mexicain compte tenu des révisions périodiques.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🔍 Mayor escrutinio a partir de 2026', NULL, NULL, 'La reforma de 2026 introduce disposiciones de responsabilidad penal por CFDIs falsos o simulados — esta es una postura de aplicación considerablemente más estricta que en años anteriores, digna de señalar a la dirección financiera.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🔍 Verschärfte Kontrolle ab 2026', NULL, NULL, 'Die Reform von 2026 führt strafrechtliche Haftungsbestimmungen für falsche oder simulierte CFDIs ein — dies ist eine spürbar schärfere Durchsetzungshaltung als in den Vorjahren, die es wert ist, der Finanzleitung gemeldet zu werden.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🔍 Contrôle renforcé à partir de 2026', NULL, NULL, 'La réforme de 2026 introduit des dispositions de responsabilité pénale pour les CFDI faux ou simulés — il s''agit d''une posture d''application nettement plus stricte que les années précédentes, à signaler à la direction financière.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '👥 Complejidad multi-RFC para contadores', NULL, NULL, 'Las firmas contables que gestionan muchos RFC de clientes enfrentan una complejidad operativa genuina para mantener los códigos de catálogo y los requisitos de complementos actualizados en cada cliente — existen herramientas de control multi-RFC dedicadas precisamente por esta razón.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '👥 Multi-RFC-Komplexität für Buchhalter', NULL, NULL, 'Buchhaltungsfirmen, die viele Kunden-RFCs verwalten, stehen vor echter operativer Komplexität, um Katalogcodes und Complemento-Anforderungen für jeden Kunden aktuell zu halten — spezielle Multi-RFC-Kontrollwerkzeuge existieren genau aus diesem Grund.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '👥 Complexité multi-RFC pour les comptables', NULL, NULL, 'Les cabinets comptables gérant de nombreux RFC clients font face à une véritable complexité opérationnelle pour maintenir les codes de catalogue et les exigences de complementos à jour pour chaque client — des outils de contrôle multi-RFC dédiés existent précisément pour cette raison.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🚢 La actualidad de los complementos importa', NULL, NULL, 'El SAT actualiza periódicamente las especificaciones de complementos individuales (Carta Porte en particular ha visto múltiples actualizaciones de versión) — rastree sus versiones específicas de complementos por separado del ritmo de actualización del CFDI base/Anexo 20.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🚢 Die Aktualität der Complementos ist entscheidend', NULL, NULL, 'Der SAT aktualisiert regelmäßig einzelne Complemento-Spezifikationen (insbesondere Carta Porte hat mehrere Versionsaktualisierungen erlebt) — verfolgen Sie Ihre spezifischen Complemento-Versionen separat vom Aktualisierungsrhythmus des Basis-CFDI/Anexo 20.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🚢 L''actualité des complementos compte', NULL, NULL, 'Le SAT met périodiquement à jour les spécifications individuelles des complementos (Carta Porte en particulier a connu plusieurs mises à jour de version) — suivez vos versions de complementos spécifiques séparément de la cadence de mise à jour du CFDI de base/Anexo 20.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Mexico' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

